using System;
using System.Collections.Generic;
using System.Linq;
using UnityEngine;

namespace WristConductor.Core
{
    public class BLECommunicationManager
    {
        public event Action<WatchDataPacket> OnDataReceived;
        public event Action<bool> OnConnectionChanged;
        public event Action<string> OnError;

        private readonly object _packetLock = new object();
        private readonly Queue<WatchDataPacket> _receiveQueue = new Queue<WatchDataPacket>();
        private readonly Dictionary<ushort, WatchDataPacket> _packetBuffer = new Dictionary<ushort, WatchDataPacket>();

        private bool _isConnected = false;
        private ushort _lastPacketId = 0;
        private int _packetLossCount = 0;
        private const int MAX_QUEUE_SIZE = 100;

        private const byte PROTOCOL_VERSION = 1;
        private const int HEADER_SIZE = 6;

        public bool IsConnected => _isConnected;

        public bool ParsePacket(byte[] rawData, out WatchDataPacket packet)
        {
            packet = new WatchDataPacket();

            if (rawData == null || rawData.Length < HEADER_SIZE)
            {
                OnError?.Invoke("���ݰ�̫��");
                return false;
            }

            try
            {
                byte version = rawData[0];
                if (version != PROTOCOL_VERSION)
                {
                    OnError?.Invoke($"��֧�ֵ�Э��汾: {version}");
                    return false;
                }

                packet.packetId = BitConverter.ToUInt16(rawData, 1);
                packet.timestamp = BitConverter.ToInt64(rawData, 3);
                packet.gesture = (GestureType)rawData[11];
                packet.confidence = rawData[12] / 255f;
                packet.flags = rawData[13];

                packet.accelerationX = BitConverter.ToSingle(rawData, 14);
                packet.accelerationY = BitConverter.ToSingle(rawData, 18);
                packet.accelerationZ = BitConverter.ToSingle(rawData, 22);
                packet.angularVelocityX = BitConverter.ToSingle(rawData, 26);
                packet.angularVelocityY = BitConverter.ToSingle(rawData, 30);
                packet.angularVelocityZ = BitConverter.ToSingle(rawData, 34);
                packet.batteryLevel = rawData[38];

                return true;
            }
            catch (Exception ex)
            {
                OnError?.Invoke($"��������: {ex.Message}");
                return false;
            }
        }

        public void ProcessReceivedData(byte[] rawData)
        {
            if (!ParsePacket(rawData, out var packet)) return;

            lock (_packetLock)
            {
                if (_packetBuffer.ContainsKey(packet.packetId)) return;

                _packetBuffer[packet.packetId] = packet;
                if (_packetBuffer.Count > 200)
                {
                    var keysToRemove = _packetBuffer.Keys.Where(k => k < packet.packetId - 100).ToList();
                    foreach (var key in keysToRemove) _packetBuffer.Remove(key);
                }

                _receiveQueue.Enqueue(packet);
                if (_receiveQueue.Count > MAX_QUEUE_SIZE) _receiveQueue.Dequeue();

                OnDataReceived?.Invoke(packet);
            }
        }

        public bool TryGetNextPacket(out WatchDataPacket packet)
        {
            lock (_packetLock)
            {
                if (_receiveQueue.Count > 0)
                {
                    packet = _receiveQueue.Dequeue();
                    return true;
                }
            }
            packet = default;
            return false;
        }

        public (int queueSize, int totalPackets, float lossRate) GetStatistics()
        {
            lock (_packetLock)
            {
                int totalPackets = _packetBuffer.Count + _receiveQueue.Count;
                float lossRate = totalPackets > 0 ? _packetLossCount / (float)totalPackets : 0;
                return (_receiveQueue.Count, totalPackets, lossRate);
            }
        }

        public void SetConnectionState(bool connected)
        {
            if (_isConnected != connected)
            {
                _isConnected = connected;
                OnConnectionChanged?.Invoke(connected);
                if (!connected)
                {
                    lock (_packetLock)
                    {
                        _receiveQueue.Clear();
                        _packetBuffer.Clear();
                        _packetLossCount = 0;
                    }
                }
            }
        }
    }
}
using System;
using System.Collections.Generic;
using UnityEngine;

namespace WristConductor.Core
{
    public class WristConductorController : IDisposable
    {
        private BLECommunicationManager _bleManager;
        private LightweightTimeSync _timeSync;
        private AccelerometerProcessor _accelerometerProcessor;
        private ScoreEngine _scoreEngine;

        private bool _isRunning = false;

        public event Action<ProcessedData> OnDataProcessed;
        public event Action<ScoreResult> OnGameFinished;
        public event Action<Rating> OnRatingChanged;
        public event Action<int> OnComboChanged;

        public bool IsRunning => _isRunning;
        public BLECommunicationManager BLEManager => _bleManager;
        public LightweightTimeSync TimeSync => _timeSync;

        public WristConductorController()
        {
            _bleManager = new BLECommunicationManager();
            _timeSync = new LightweightTimeSync();
            _accelerometerProcessor = new AccelerometerProcessor();

            _bleManager.OnDataReceived += OnBLEDataReceived;
        }

        private void OnBLEDataReceived(WatchDataPacket packet)
        {
            try
            {
                long localTime = _timeSync.WatchToLocal(packet.timestamp);
                var processed = ProcessData(packet, localTime);
                
                if (_scoreEngine != null && _scoreEngine.IsActive)
                {
                    _scoreEngine.ProcessInput(processed, DateTimeOffset.UtcNow.ToUnixTimeMilliseconds());
                }

                OnDataProcessed?.Invoke(processed);
            }
            catch (Exception ex)
            {
                Debug.LogError($"处理数据错误: {ex.Message}");
            }
        }

        private ProcessedData ProcessData(WatchDataPacket packet, long localTime)
        {
            var (filteredX, filteredY, filteredZ, magnitude) =
                _accelerometerProcessor.Process(packet.accelerationX, packet.accelerationY, packet.accelerationZ);

            return new ProcessedData
            {
                timestamp = localTime,
                gesture = packet.gesture,
                filteredAccelX = filteredX,
                filteredAccelY = filteredY,
                filteredAccelZ = filteredZ,
                gestureConfidence = packet.confidence,
                movementMagnitude = magnitude,
                localTimeOffset = localTime - packet.timestamp
            };
        }

        public bool StartGame(List<MusicNote> notes, long songStartTime)
        {
            try
            {
                _scoreEngine = new ScoreEngine(notes);
                _scoreEngine.OnComboChanged += OnComboChangedInternal;
                _scoreEngine.OnSongComplete += OnSongCompleteInternal;
                _scoreEngine.Start(songStartTime);
                _isRunning = true;

                Debug.Log($"游戏开始，音符数: {notes.Count}");
                return true;
            }
            catch (Exception ex)
            {
                Debug.LogError($"启动游戏失败: {ex.Message}");
                return false;
            }
        }

        private void OnComboChangedInternal(int combo)
        {
            OnComboChanged?.Invoke(combo);
        }

        private void OnSongCompleteInternal(ScoreResult result)
        {
            _isRunning = false;
            OnRatingChanged?.Invoke(result.rating);
            OnGameFinished?.Invoke(result);
            Debug.Log($"游戏结束! 评级: {result.rating}, 得分: {result.totalScore}");
        }

        public void StopGame()
        {
            if (_scoreEngine != null && _scoreEngine.IsActive)
            {
                var result = _scoreEngine.GetResult();
                OnSongCompleteInternal(result);
            }
            _isRunning = false;
        }

        public void Reset()
        {
            StopGame();
            _accelerometerProcessor.Reset();
            _timeSync.Reset();
            _bleManager.SetConnectionState(false);
        }

        public void Dispose()
        {
            StopGame();
            if (_bleManager != null)
            {
                _bleManager.OnDataReceived -= OnBLEDataReceived;
            }
        }
    }
}
using System;
using System.Collections.Generic;

namespace WristConductor.Core
{
    #region 枚举定义

    /// <summary>
    /// 手势动作类型
    /// </summary>
    public enum GestureType
    {
        None = 0,
        Tap = 1,
        SwipeUp = 2,
        SwipeDown = 3,
        SwipeLeft = 4,
        SwipeRight = 5,
        LongPress = 6,
        Flick = 7
    }

    /// <summary>
    /// 命中结果
    /// </summary>
    public enum HitResult
    {
        Miss = 0,
        Good = 1,
        Perfect = 2
    }

    /// <summary>
    /// 评级
    /// </summary>
    public enum Rating
    {
        None = 0,
        D = 1,
        C = 2,
        B = 3,
        A = 4,
        S = 5,
        SS = 6,
        SSS = 7
    }

    #endregion

    #region 数据结构

    /// <summary>
    /// 从智能手表接收的原始数据包
    /// </summary>
    [Serializable]
    public struct WatchDataPacket
    {
        public long timestamp;
        public GestureType gesture;
        public float accelerationX;
        public float accelerationY;
        public float accelerationZ;
        public float angularVelocityX;
        public float angularVelocityY;
        public float angularVelocityZ;
        public float confidence;
        public byte batteryLevel;
        public ushort packetId;
        public byte flags;

        public bool IsValid => gesture != GestureType.None && confidence > 0.5f;
    }

    /// <summary>
    /// 预处理后的数据
    /// </summary>
    public struct ProcessedData
    {
        public long timestamp;
        public GestureType gesture;
        public float filteredAccelX;
        public float filteredAccelY;
        public float filteredAccelZ;
        public float gestureConfidence;
        public float movementMagnitude;
        public long localTimeOffset;
    }

    /// <summary>
    /// 乐谱音符
    /// </summary>
    [Serializable]
    public class MusicNote
    {
        public long timestamp;
        public long duration;
        public GestureType gestureType;
        public float minConfidence;
        public float difficultyWeight;
        public bool isLongNote;
        public int beatIndex;
        public float toleranceWindow;

        public MusicNote Clone()
        {
            return new MusicNote
            {
                timestamp = this.timestamp,
                duration = this.duration,
                gestureType = this.gestureType,
                minConfidence = this.minConfidence,
                difficultyWeight = this.difficultyWeight,
                isLongNote = this.isLongNote,
                beatIndex = this.beatIndex,
                toleranceWindow = this.toleranceWindow
            };
        }
    }

    /// <summary>
    /// 评分结果
    /// </summary>
    public struct ScoreResult
    {
        public int totalCombo;
        public int maxCombo;
        public int perfectCount;
        public int goodCount;
        public int missCount;
        public int totalScore;
        public float accuracy;
        public long averageLatency;
        public Rating rating;
        public Dictionary<int, float> noteLatencies;

        // 构造函数
        public ScoreResult(bool initialize)
        {
            totalCombo = 0;
            maxCombo = 0;
            perfectCount = 0;
            goodCount = 0;
            missCount = 0;
            totalScore = 0;
            accuracy = 0;
            averageLatency = 0;
            rating = Rating.None;
            noteLatencies = new Dictionary<int, float>();
        }
    }

    #endregion
}

