using System.Collections.Generic;
using WristConductor.Core;
using UnityEngine;

namespace WristConductor
{
    /// <summary>
    /// Unity-side bridge for the Android BLE plugin. Attach this component to a
    /// persistent GameObject, then configure the BLE UUIDs in the Inspector.
    /// </summary>
    public sealed class AndroidBleBridge : MonoBehaviour
    {
        [Header("BLE configuration")]
        [SerializeField] private string serviceUuid = "";
        [SerializeField] private string notifyCharacteristicUuid = "";
        [SerializeField] private bool scanForNamedDeviceOnly = false;
        [SerializeField] private string deviceName = "";

        public BLECommunicationManager CommunicationManager { get; private set; }
        public bool IsSupported => Application.platform == RuntimePlatform.Android;
        public event Action<string> OnStatusChanged;
        public event Action<BleDeviceInfo> OnDeviceFound;

        private const string PluginClass = "com.wristconductor.ble.UnityBlePlugin";
        private const int ExpectedPacketSize = 39;
        private readonly List<byte> receiveBuffer = new List<byte>();

        private void Awake()
        {
            CommunicationManager = new BLECommunicationManager();
            CommunicationManager.OnConnectionChanged += connected =>
                OnStatusChanged?.Invoke(connected ? "Connected" : "Disconnected");
            CommunicationManager.OnError += error => OnStatusChanged?.Invoke($"Error: {error}");
            DontDestroyOnLoad(gameObject);
        }

        public void StartScan()
        {
#if UNITY_ANDROID && !UNITY_EDITOR
            StartCoroutine(RequestPermissionsAndStartScan());
#else
            OnStatusChanged?.Invoke("BLE is available only in an Android build.");
#endif
        }

        public void Connect(string deviceAddress)
        {
            if (string.IsNullOrWhiteSpace(deviceAddress))
            {
                OnStatusChanged?.Invoke("Error: a device address is required.");
                return;
            }
            if (!HasValidConfiguration()) return;

#if UNITY_ANDROID && !UNITY_EDITOR
            using (var plugin = new AndroidJavaClass(PluginClass))
            {
                plugin.CallStatic("connect", deviceAddress);
            }
#else
            OnStatusChanged?.Invoke("BLE is available only in an Android build.");
#endif
        }

        public void Disconnect()
        {
#if UNITY_ANDROID && !UNITY_EDITOR
            using (var plugin = new AndroidJavaClass(PluginClass))
            {
                plugin.CallStatic("disconnect");
            }
#endif
            CommunicationManager.SetConnectionState(false);
        }

        // Called from Android through UnityPlayer.UnitySendMessage.
        public void OnAndroidBleData(string base64Packet)
        {
            try
            {
                var fragment = Convert.FromBase64String(base64Packet);
                receiveBuffer.AddRange(fragment);
                while (receiveBuffer.Count >= ExpectedPacketSize)
                {
                    var packet = receiveBuffer.GetRange(0, ExpectedPacketSize).ToArray();
                    receiveBuffer.RemoveRange(0, ExpectedPacketSize);
                    CommunicationManager.ProcessReceivedData(packet);
                }
            }
            catch (FormatException)
            {
                OnStatusChanged?.Invoke("Error: Android returned invalid Base64 data.");
            }
        }

        public void OnAndroidBleConnected(string ignored)
        {
            CommunicationManager.SetConnectionState(true);
        }

        public void OnAndroidBleDisconnected(string ignored)
        {
            receiveBuffer.Clear();
            CommunicationManager.SetConnectionState(false);
        }

        public void OnAndroidBleError(string error)
        {
            OnStatusChanged?.Invoke($"Error: {error}");
        }

        public void OnAndroidBleStatus(string status)
        {
            OnStatusChanged?.Invoke(status);
        }

        // Called from Android with a URL-encoded "device name\nMAC address" value.
        public void OnAndroidBleDeviceFound(string encodedDevice)
        {
            var parts = Uri.UnescapeDataString(encodedDevice).Split('\n');
            if (parts.Length != 2) return;
            OnDeviceFound?.Invoke(new BleDeviceInfo(parts[0], parts[1]));
        }

#if UNITY_ANDROID && !UNITY_EDITOR
        private System.Collections.IEnumerator RequestPermissionsAndStartScan()
        {
            var permissionNames = new List<string>();
            using (var version = new AndroidJavaClass("android.os.Build$VERSION"))
            {
                if (version.GetStatic<int>("SDK_INT") >= 31)
                {
                    permissionNames.Add("android.permission.BLUETOOTH_SCAN");
                    permissionNames.Add("android.permission.BLUETOOTH_CONNECT");
                }
                else
                {
                    permissionNames.Add("android.permission.ACCESS_FINE_LOCATION");
                }
            }

            foreach (var permissionName in permissionNames)
            {
                if (!UnityEngine.Android.Permission.HasUserAuthorizedPermission(permissionName))
                    UnityEngine.Android.Permission.RequestUserPermission(permissionName);
            }

            // Permission dialogs complete asynchronously. Wait briefly before checking.
            yield return new WaitForSeconds(1f);
            foreach (var permissionName in permissionNames)
            {
                if (!UnityEngine.Android.Permission.HasUserAuthorizedPermission(permissionName))
                {
                    OnStatusChanged?.Invoke("Bluetooth permission was not granted.");
                    yield break;
                }
            }

            using (var plugin = new AndroidJavaClass(PluginClass))
            {
                plugin.CallStatic("startScan", gameObject.name, serviceUuid,
                    notifyCharacteristicUuid, scanForNamedDeviceOnly ? deviceName : "");
            }
        }
#endif

        private bool HasValidConfiguration()
        {
            var missing = new List<string>();
            if (string.IsNullOrWhiteSpace(serviceUuid)) missing.Add("service UUID");
            if (string.IsNullOrWhiteSpace(notifyCharacteristicUuid)) missing.Add("notify characteristic UUID");
            if (missing.Count == 0) return true;

            OnStatusChanged?.Invoke($"BLE configuration missing: {string.Join(", ", missing)}.");
            return false;
        }
    }

    public readonly struct BleDeviceInfo
    {
        public readonly string Name;
        public readonly string Address;

        public BleDeviceInfo(string name, string address)
        {
            Name = string.IsNullOrWhiteSpace(name) ? "Unnamed BLE device" : name;
            Address = address;
        }
    }
}

using System.Collections.Generic;
using UnityEngine;

namespace WristConductor
{
    /// <summary>
    /// Temporary on-screen BLE test panel. Remove it when the production UI is ready.
    /// </summary>
    public sealed class AndroidBleDebugPanel : MonoBehaviour
    {
        [SerializeField] private AndroidBleBridge bridge;

        private readonly List<BleDeviceInfo> devices = new List<BleDeviceInfo>();
        private string status = "Ready";
        private Vector2 scrollPosition;

        private void Awake()
        {
            if (bridge == null) bridge = FindFirstObjectByType<AndroidBleBridge>();
        }

        private void OnEnable()
        {
            if (bridge == null) return;
            bridge.OnStatusChanged += SetStatus;
            bridge.OnDeviceFound += AddDevice;
        }

        private void OnDisable()
        {
            if (bridge == null) return;
            bridge.OnStatusChanged -= SetStatus;
            bridge.OnDeviceFound -= AddDevice;
        }

        private void OnGUI()
        {
            if (bridge == null)
            {
                GUI.Label(new Rect(24, 24, 900, 60), "AndroidBleBridge is not assigned.");
                return;
            }

            const float scale = 1.5f;
            var oldMatrix = GUI.matrix;
            GUI.matrix = Matrix4x4.Scale(new Vector3(scale, scale, 1f));

            GUILayout.BeginArea(new Rect(16, 16, Screen.width / scale - 32, Screen.height / scale - 32), GUI.skin.box);
            GUILayout.Label("BLE test panel");
            GUILayout.Label("Status: " + status);

            GUILayout.BeginHorizontal();
            if (GUILayout.Button("Scan nearby devices", GUILayout.Height(52)))
            {
                devices.Clear();
                bridge.StartScan();
            }
            if (GUILayout.Button("Disconnect", GUILayout.Height(52))) bridge.Disconnect();
            GUILayout.EndHorizontal();

            GUILayout.Label("Tap a device to connect after entering its UUIDs in AndroidBleBridge.");
            scrollPosition = GUILayout.BeginScrollView(scrollPosition);
            foreach (var device in devices)
            {
                if (GUILayout.Button($"{device.Name}\n{device.Address}", GUILayout.Height(70)))
                    bridge.Connect(device.Address);
            }
            GUILayout.EndScrollView();
            GUILayout.EndArea();

            GUI.matrix = oldMatrix;
        }

        private void SetStatus(string value)
        {
            status = value;
        }

        private void AddDevice(BleDeviceInfo device)
        {
            if (devices.Exists(item => item.Address == device.Address)) return;
            devices.Add(device);
        }
    }
}

using UnityEngine;
using TMPro;

public class GameManagerExample : MonoBehaviour
{
    [Header("UI References")]
    public TMP_Text scoreText;
    public TMP_Text comboText;
    public TMP_Text statusText;
    public TMP_Text ratingText;

    private int combo = 0;
    private int score = 0;
    private bool isRunning = false;

    void Start()
    {
        Debug.Log("🎮 游戏启动!");
        UpdateUI();
        isRunning = true;
        statusText.text = "按 空格键 模拟命中";
    }

    void Update()
    {
        if (!isRunning) return;

        if (Input.GetKeyDown(KeyCode.Space))
        {
            HitNote();
        }

        if (Input.GetKeyDown(KeyCode.R))
        {
            ResetGame();
        }
    }

    void HitNote()
    {
        combo++;
        score += 100 + (combo / 10) * 10;
        statusText.text = $"🎯 命中! 连击 x{combo}";
        UpdateUI();
    }

    void UpdateUI()
    {
        if (comboText != null) comboText.text = $"连击: {combo}";
        if (scoreText != null) scoreText.text = $"得分: {score}";
        if (ratingText != null) ratingText.text = $"评级: {GetRating()}";
    }

    string GetRating()
    {
        if (score >= 2000) return "SSS";
        if (score >= 1500) return "SS";
        if (score >= 1000) return "S";
        if (score >= 700) return "A";
        if (score >= 400) return "B";
        if (score >= 200) return "C";
        return "D";
    }

    void ResetGame()
    {
        combo = 0;
        score = 0;
        statusText.text = "🔄 已重置，按空格继续";
        UpdateUI();
    }
}
