   7:     public class WristConductorController : IDisposable
   8:     {
   9:         private BLECommunicationManager _bleManager;
  10:         private LightweightTimeSync _timeSync;
  11:         private AccelerometerProcessor _accelerometerProcessor;
  12:         private ScoreEngine _scoreEngine;
  13: 
  14:         private bool _isRunning = false;
  15: 
  16:         public event Action<ProcessedData> OnDataProcessed;
  17:         public event Action<ScoreResult> OnGameFinished;
  18:         public event Action<Rating> OnRatingChanged;
  19:         public event Action<int> OnComboChanged;
  20: 
  21:         public bool IsRunning => _isRunning;
  22:         public BLECommunicationManager BLEManager => _bleManager;
  23:         public LightweightTimeSync TimeSync => _timeSync;
  24: 
  25:         public WristConductorController()
  26:         {
  27:             _bleManager = new BLECommunicationManager();
  28:             _timeSync = new LightweightTimeSync();
  29:             _accelerometerProcessor = new AccelerometerProcessor();
  30: 
  31:             _bleManager.OnDataReceived += OnBLEDataReceived;
  32:         }
  33: 
  34:         private void OnBLEDataReceived(WatchDataPacket packet)
  35:         {
  36:             try
  37:             {
  38:                 long localTime = _timeSync.WatchToLocal(packet.timestamp);
  39:                 var processed = ProcessData(packet, localTime);
  40:                 
  41:                 if (_scoreEngine != null && _scoreEngine.IsActive)
  42:                 {
  43:                     _scoreEngine.ProcessInput(processed, DateTimeOffset.UtcNow.ToUnixTimeMilliseconds());
  44:                 }
  45: 
  46:                 OnDataProcessed?.Invoke(processed);
  47:             }
  48:             catch (Exception ex)
  49:             {
  50:                 Debug.LogError($"处理数据错误: {ex.Message}");
  51:             }
  52:         }
  53: 
  54:         private ProcessedData ProcessData(WatchDataPacket packet, long localTime)
  55:         {
  56:             var (filteredX, filteredY, filteredZ, magnitude) =
  57:                 _accelerometerProcessor.Process(packet.accelerationX, packet.accelerationY, packet.accelerationZ);
  58: 
  59:             return new ProcessedData
  60:             {
  61:                 timestamp = localTime,
  62:                 gesture = packet.gesture,
  63:                 filteredAccelX = filteredX,
  64:                 filteredAccelY = filteredY,
  65:                 filteredAccelZ = filteredZ,
  66:                 gestureConfidence = packet.confidence,
  67:                 movementMagnitude = magnitude,
  68:                 localTimeOffset = localTime - packet.timestamp
  69:             };
  70:         }
  71: 
  72:         public bool StartGame(List<MusicNote> notes, long songStartTime)
  73:         {
  74:             try
  75:             {
  76:                 _scoreEngine = new ScoreEngine(notes);
  77:                 _scoreEngine.OnComboChanged += OnComboChangedInternal;
  78:                 _scoreEngine.OnSongComplete += OnSongCompleteInternal;
  79:                 _scoreEngine.Start(songStartTime);
  80:                 _isRunning = true;
  81: 
  82:                 Debug.Log($"游戏开始，音符数: {notes.Count}");
  83:                 return true;
  84:             }
  85:             catch (Exception ex)
  86:             {
  87:                 Debug.LogError($"启动游戏失败: {ex.Message}");
  88:                 return false;
  89:             }
  90:         }
  91: 
  92:         private void OnComboChangedInternal(int combo)
  93:         {
  94:             OnComboChanged?.Invoke(combo);
  95:         }
  96: 
  97:         private void OnSongCompleteInternal(ScoreResult result)
  98:         {
  99:             _isRunning = false;
 100:             OnRatingChanged?.Invoke(result.rating);
 101:             OnGameFinished?.Invoke(result);
 102:             Debug.Log($"游戏结束! 评级: {result.rating}, 得分: {result.totalScore}");
 103:         }
 104: 
 105:         public void StopGame()
 106:         {
 107:             if (_scoreEngine != null && _scoreEngine.IsActive)
 108:             {
 109:                 var result = _scoreEngine.GetResult();
 110:                 OnSongCompleteInternal(result);
 111:             }
 112:             _isRunning = false;
 113:         }
 114: 
 115:         public void Reset()
 116:         {
 117:             StopGame();
 118:             _accelerometerProcessor.Reset();
 119:             _timeSync.Reset();
 120:             _bleManager.SetConnectionState(false);
 121:         }
 122: 
 123:         public void Dispose()
 124:         {
 125:             StopGame();
 126:             if (_bleManager != null)
 127:             {
 128:                 _bleManager.OnDataReceived -= OnBLEDataReceived;
 129:             }
 130:         }
 131:     }
 132: }
