  1: using System;
  2: using System.Collections.Generic;
  3: using System.Linq;
  4: using UnityEngine;
  5: 
  6: namespace WristConductor.Core
  7: {
  8:     public class ScoreEngine
  9:     {
 10:         public event Action<int> OnComboChanged;
 11:         public event Action<HitResult, int> OnNoteHit;
 12:         public event Action<ScoreResult> OnSongComplete;
 13: 
 14:         private readonly List<MusicNote> _notes;
 15:         private readonly Queue<MusicNote> _pendingNotes = new Queue<MusicNote>();
 16: 
 17:         private int _currentCombo = 0;
 18:         private int _maxCombo = 0;
 19:         private int _perfectCount = 0;
 20:         private int _goodCount = 0;
 21:         private int _missCount = 0;
 22:         private int _totalScore = 0;
 23:         private long _totalLatency = 0;
 24:         private int _hitCount = 0;
 25: 
 26:         private float _currentToleranceWindow = 150f;
 27:         private float _minToleranceWindow = 80f;
 28:         private float _maxToleranceWindow = 250f;
 29:         private bool _isActive = false;
 30:         private long _songStartTime = 0;
 31: 
 32:         private const int PERFECT_SCORE = 100;
 33:         private const int GOOD_SCORE = 50;
 34:         private const int COMBO_BONUS_STEP = 50;
 35: 
 36:         private readonly List<float> _latencyHistory = new List<float>();
 37:         private float _averageLatency = 0f;
 38: 
 39:         public bool IsActive => _isActive;
 40:         public int CurrentCombo => _currentCombo;
 41:         public int MaxCombo => _maxCombo;
 42: 
 43:         public ScoreEngine(List<MusicNote> notes)
 44:         {
 45:             _notes = notes.OrderBy(n => n.timestamp).ToList();
 46:             foreach (var note in _notes) _pendingNotes.Enqueue(note.Clone());
 47:         }
 48: 
 49:         public void Start(long songStartTime)
 50:         {
 51:             _isActive = true;
 52:             _songStartTime = songStartTime;
 53:             _currentCombo = 0;
 54:             _maxCombo = 0;
 55:             _perfectCount = 0;
 56:             _goodCount = 0;
 57:             _missCount = 0;
 58:             _totalScore = 0;
 59:             _totalLatency = 0;
 60:             _hitCount = 0;
 61:             _latencyHistory.Clear();
 62:             _averageLatency = 0;
 63:         }
 64: 
 65:         public void ProcessInput(ProcessedData input, long currentLocalTime)
 66:         {
 67:             if (!_isActive || _pendingNotes.Count == 0) return;
 68: 
 69:             var nextNote = _pendingNotes.Peek();
 70:             long localNoteTime = _songStartTime + nextNote.timestamp;
 71:             long timeDiff = currentLocalTime - localNoteTime;
 72:             float timeDiffMs = Math.Abs(timeDiff);
 73: 
 74:             if (timeDiff > _currentToleranceWindow * 1.5f)
 75:             {
 76:                 HandleMiss(nextNote);
 77:                 _pendingNotes.Dequeue();
 78:                 return;
 79:             }
 80: 
 81:             if (input.gesture == nextNote.gestureType && input.gestureConfidence >= nextNote.minConfidence)
 82:             {
 83:                 if (timeDiffMs <= _currentToleranceWindow)
 84:                 {
 85:                     HitResult result = timeDiffMs / _currentToleranceWindow <= 0.3f ? 
 86:                         HitResult.Perfect : HitResult.Good;
 87:                     HandleHit(nextNote, result, timeDiff);
 88:                     _pendingNotes.Dequeue();
 89:                 }
 90:             }
 91:         }
 92: 
 93:         private void HandleHit(MusicNote note, HitResult result, long latency)
 94:         {
 95:             _currentCombo++;
 96:             if (_currentCombo > _maxCombo) _maxCombo = _currentCombo;
 97:             OnComboChanged?.Invoke(_currentCombo);
 98: 
 99:             int baseScore = result == HitResult.Perfect ? PERFECT_SCORE : GOOD_SCORE;
100:             int comboBonus = (_currentCombo / COMBO_BONUS_STEP) * 10;
101:             float difficultyBonus = 1 + (note.difficultyWeight * 0.1f);
102:             int finalScore = (int)((baseScore + comboBonus) * difficultyBonus);
103: 
104:             _totalScore += finalScore;
105:             if (result == HitResult.Perfect) _perfectCount++;
106:             else _goodCount++;
107: 
108:             _totalLatency += Math.Abs(latency);
109:             _hitCount++;
110:             _averageLatency = _totalLatency / (float)_hitCount;
111: 
112:             OnNoteHit?.Invoke(result, finalScore);
113:         }
114: 
115:         private void HandleMiss(MusicNote note)
116:         {
117:             _currentCombo = 0;
118:             _missCount++;
119:             OnComboChanged?.Invoke(0);
120:             OnNoteHit?.Invoke(HitResult.Miss, 0);
121:         }
122: 
123:         public ScoreResult GetResult()
124:         {
125:             _isActive = false;
126:             while (_pendingNotes.Count > 0)
127:             {
128:                 _pendingNotes.Dequeue();
129:                 _missCount++;
130:             }
131: 
132:             var result = new ScoreResult(true)
133:             {
134:                 totalCombo = _currentCombo,
135:                 maxCombo = _maxCombo,
136:                 perfectCount = _perfectCount,
137:                 goodCount = _goodCount,
138:                 missCount = _missCount,
139:                 totalScore = _totalScore,
140:                 averageLatency = _hitCount > 0 ? _totalLatency / _hitCount : 0,
141:                 rating = CalculateRating()
142:             };
143: 
144:             int totalHits = _perfectCount + _goodCount;
145:             result.accuracy = _notes.Count > 0 ? totalHits / (float)_notes.Count : 0;
146: 
147:             OnSongComplete?.Invoke(result);
148:             return result;
149:         }
150: 
151:         private Rating CalculateRating()
152:         {
153:             if (_notes.Count == 0) return Rating.None;
154:             float perfectRate = _perfectCount / (float)_notes.Count;
155:             float scoreRate = _totalScore / (float)(_notes.Count * PERFECT_SCORE);
156: 
157:             if (scoreRate >= 0.98f && perfectRate >= 0.95f) return Rating.SSS;
158:             if (scoreRate >= 0.95f && perfectRate >= 0.85f) return Rating.SS;
159:             if (scoreRate >= 0.90f) return Rating.S;
160:             if (scoreRate >= 0.80f) return Rating.A;
161:             if (scoreRate >= 0.70f) return Rating.B;
162:             if (scoreRate >= 0.60f) return Rating.C;
163:             if (scoreRate >= 0.50f) return Rating.D;
164:             return Rating.None;
165:         }
166: 
167:         public (int notesRemaining, float tolerance, float avgLatency) GetStatistics()
168:         {
169:             return (_pendingNotes.Count, _currentToleranceWindow, _averageLatency);
170:         }
171:     }
172: }

