L572:     int32_t LSM_I2C_Write(void *ctx, uint8_t reg, uint8_t *data, uint16_t len)
L573:     {
L574:         rt_size_t res;
L575:         struct LSM6DSL_CONT_T *handle = (struct LSM6DSL_CONT_T *)ctx;
L576: 
L577:         if (handle && handle->bus_handle && data)
L578:         {
L579:             uint16_t addr16 = (uint16_t)reg;
L580:             res = rt_i2c_mem_write(handle->bus_handle, handle->dev_addr, addr16, 8, data, len);
L581:             if (res > 0)
L582:                 return 0;
L583:             else
L584:                 return -2;
L585:         }
L586: 
L587:         return -3;
L588:     }
